package net.minecraft.world.entity.npc;import net.minecraft.core.BlockPos;public class Villager {public BlockPos position=new BlockPos(0,0,0);public Navigation getNavigation(){return new Navigation();}public static class Navigation { public boolean moveTo(double x,double y,double z,double speed){return true;}}public boolean isAlive(){return true;}public double distanceToSqr(double x,double y,double z){return Math.pow(position.getX()+0.5-x,2)+Math.pow(position.getY()+0.5-y,2)+Math.pow(position.getZ()+0.5-z,2);}}